DIR=File.expand_path(File.dirname(__FILE__))
TEMPLATE=File.expand_path('../Margo-conteudos-pre-lancamento-atualizado.docx',__dir__)
POSTS=[
{date:'20/10',day:'TERÇA-FEIRA',format:'CARROSSEL · FOTOGRAFIA + ILUSTRAÇÃO',title:'A mesinha da janela',purpose:'Fazer a pessoa imaginar a própria pausa na casa e convidar uma companhia para vir.',idea:'Apresentar a mesinha com vista sugerida pela Bruna: o lugar, o que se vê dali e uma mesa montada para ficar um pouco. A personagem Margô pode ocupar uma das cadeiras na edição, como anfitriã. O ambiente real continua sendo o protagonista.',show:['A mesa inteira e sua relação com a janela e a vista.','O mesmo enquadramento com um pedido real servido.','Detalhes da louça, da luz e de uma pessoa chegando ou se acomodando.','Uma imagem da mesa sem pessoas para inserir a personagem depois.'],photos:['Mesa vazia, de frente, com as duas cadeiras e espaço ao redor.','Mesa montada: plano aberto, plano aproximado e vista de quem está sentado.','Foto limpa da cadeira em que a Margô poderá sentar; manter ângulo e luz das outras fotos.'],videos:['Vista pela janela e pedido chegando à mesa: 2 ou 3 clipes curtos de apoio, caso a pauta vire Reel.'],people:'Uma companhia pode participar com mãos ou costas; não depende de fala. A personagem será adicionada depois, sem substituir os registros da casa.',note:'Ideia enviada pela Bruna. “Mais movimentada” fica como observação interna da sócia, sem transformar isso em ranking ou dado público. A mesa não é apresentada como reservável.',approval:'Aprovar o uso da mesinha como primeiro convite pós-depoimentos e se a personagem entra em uma ou duas fotos.'},
{date:'22/10',day:'QUINTA-FEIRA',format:'REEL SENSORIAL · 12 A 18 SEGUNDOS',title:'Uma pausa que dá vontade de provar',purpose:'Mostrar café e comida como um motivo concreto para sair de casa e fazer uma pausa na Margô.',idea:'Usar a focaccia com molhos para construir uma pequena experiência: abrir o pão, escolher um molho, servir o café e deixar a mesa pronta. O produto dá textura ao convite, sem virar uma peça de oferta ou uma explicação de ficha técnica.',show:['Uma ação apetitosa já no primeiro plano: abrir a focaccia ou mergulhar um pedaço no molho.','O pedido completo, sem ficar só em detalhes abstratos.','Uma mão pegando um pedaço e a bebida sendo servida.','Um fechamento visual com a mesa e parte do ambiente.'],photos:['Prato completo antes de abrir ou provar.','Miolo, molhos e combinação visual com uma bebida realmente disponível.'],videos:['Focaccia sendo aberta: filmar mais de uma tentativa.','Pedaço encontrando o molho; café sendo servido; mão levando o pedido à mesa.','Captar som real dessas ações por alguns segundos, sem conversa por cima.'],people:'Mãos e gestos bastam; não precisa de ninguém falando para a câmera.',note:'Escolher a versão disponível no domingo. Se mostrar a opção vegana, usar somente os acompanhamentos correspondentes. Não simular textura nem prometer que o prato será compartilhável sem confirmar.',approval:'Aprovar a focaccia como protagonista sensorial. Se o preparo não puder ser captado, manter mesa e gesto de servir como alternativa.'},
{date:'24/10',day:'SÁBADO',format:'REEL DE EXPERIÊNCIA · 15 A 25 SEGUNDOS',title:'Uma manhã de domingo na Margô',purpose:'Dar uma ideia de programa para o domingo seguinte e mostrar como é estar na casa.',idea:'Um passeio curto vivido pelo olhar de quem chega: entrar, olhar a casa, escolher uma mesa, receber um pedido e ficar. A manhã do dia 18 será a base visual para convidar à visita do dia 25.',show:['Uma mesa com pedido e luz da manhã, antes de revelar o percurso.','Chegada pela entrada real e descoberta do salão.','Atendimento, café chegando e um momento de permanência.','Pequenas ações reais: conversar, olhar a vista ou abrir um livro.'],photos:['Uma mesa de domingo com o ambiente ao fundo.','Planos abertos da casa e detalhes de luz.'],videos:['Chegada, porta, percurso e mesa: cada ação em um clipe separado.','Pedido servido, reação natural e um plano mais longo de alguém aproveitando a pausa.','Som de passos, louça e ambiente para apoiar a edição.'],people:'Idealmente uma ou duas pessoas que aceitem participar. Sem figurante disponível, usar o ponto de vista de quem chega e as mãos em cena.',note:'Confirmar no dia os horários vigentes; a base atual é domingo das 9h às 16h. Não sugerir buffet, brunch ou uma oferta de café da manhã que a operação não confirmou.',approval:'Aprovar domingo como ocasião de visita, sem tratar esse dia como um problema de movimento.'},
{date:'27/10',day:'TERÇA-FEIRA',format:'REEL DE CONVERSA · 20 A 30 SEGUNDOS',title:'O café começa numa conversa',purpose:'Deixar a visita a uma cafeteria de cafés especiais mais próxima e acolhedora para quem ainda não conhece.',idea:'Mostrar alguém da equipe acolhendo uma dúvida comum e ajudando a escolher um café pelo gosto da pessoa. O preparo entra como imagem de apoio. A proposta é fazer o público sentir que pode chegar sem precisar entender de café.',show:['Uma troca simples entre pessoa da equipe e cliente/participante.','Duas opções reais disponíveis, com indicação acessível do que muda entre elas.','Mãos preparando o café e a xícara chegando à mesa.','A pessoa provando ou continuando a conversa.'],photos:['Pessoa que prepara o café e uma xícara pronta.','Grãos/embalagens que a equipe escolher apresentar.'],videos:['Registrar a orientação espontânea em um ponto menos ruidoso.','Moagem, método, servir e entrega da xícara.','Gravar uma versão curta da explicação, sem termos técnicos em excesso.'],people:'Pergunta de captação: como vocês ajudam quem chega sem saber o que pedir? Não é uma fala para decorar. Se ninguém quiser aparecer, gravar mãos e explicação em off.',note:'Grãos e descrições serão escolhidos com o barista. Notas sensoriais não devem ser tratadas como ingredientes adicionados. Não fechar copy antes dessa conversa.',approval:'Aprovar o foco no acolhimento e confirmar quem da equipe topa participar.'},
{date:'29/10',day:'QUINTA-FEIRA',format:'REEL DE BASTIDORES · 15 A 25 SEGUNDOS',title:'Da cozinha até a sua mesa',purpose:'Mostrar o cuidado e as pessoas por trás da experiência, dando vontade de conhecer a comida da casa.',idea:'Acompanhar um pedido sendo feito e servido, com presença de quem prepara. O Croque Meu Senhor é a primeira opção, por permitir ver montagem, gratinado e corte. Mais do que listar ingredientes, queremos mostrar o gesto de fazer e de receber.',show:['Rosto ou mãos de quem prepara e uma etapa marcante do pedido.','Montagem, saída do forno e finalização, conforme a rotina real.','Pedido saindo da cozinha e chegando à mesa.','Pessoas aproveitando ou um detalhe do corte antes da primeira garfada.'],photos:['Prato completo e corte, antes de começar a consumir.','Retrato espontâneo de quem preparou e detalhe das mãos.'],videos:['Sequência do Croque: montagem, bechamel/queijos, gratinado, corte e serviço.','Se possível, uma observação curta de quem cozinha sobre o cuidado com esse pedido.','Som real de preparo, louça e pedido chegando.'],people:'Bruna pode aparecer se estiver disponível, mas a pauta também funciona com outra pessoa da cozinha ou só com mãos e voz.',note:'A escolha final do prato depende da captação e do serviço de domingo. Não pedir repetição de uma etapa que atrapalhe a operação; usar um prato que realmente será preparado.',approval:'Aprovar bastidor como forma de mostrar carinho e autoria; confirmar prato e participante após a visita.'},
{date:'31/10',day:'SÁBADO',format:'CARROSSEL FOTOGRÁFICO · 5 A 6 IMAGENS',title:'Uma casa, diferentes jeitos de ficar',purpose:'Gerar identificação e convite para visitar, mostrando que a casa pode fazer parte de momentos diferentes da rotina.',idea:'Um ensaio leve de vida na Margô: companhia, conversa, uma pausa só sua, café e comida acontecendo no mesmo espaço. Fechar o mês com a casa sendo vivida, sem retrospectiva de inauguração nem balanço de um mês que ainda não se completou.',show:['Um encontro à mesa com gestos naturais.','Uma pausa individual, sem precisar encenar trabalho ou produtividade.','Um pedido entre pessoas e um detalhe do ambiente.','Uma imagem aberta que situe os momentos na mesma casa.'],photos:['Dupla conversando, mãos à mesa e uma pessoa aproveitando uma pausa.','Pedido servido com gente e ambiente no enquadramento.','Plano aberto e um detalhe de objeto, luz ou louça que caracterize a Margô.'],videos:['Clipes extras das mesmas ações, só para banco de Stories ou eventual adaptação; não são essenciais para este carrossel.'],people:'Pessoas que aceitem participar, sem pedir poses ou reações forçadas. Se não houver participantes, usar mesas vividas, mãos e objetos de uma pausa real.',note:'Não inventar programação de Halloween. A pauta é sobre possibilidades reais de uso da casa; não exige que toda cena aconteça no domingo nem que todos os clientes apareçam.',approval:'Aprovar um fechamento de mês centrado na vontade de estar ali. A seleção final depende das fotos conseguidas.'}
]
File.write(File.join(DIR,'pautas.json'),JSON.pretty_generate(POSTS))
def esc(s); CGI.escapeHTML(s.to_s);end
def para(s,style:nil,color:nil,size:nil,bold:false,after:120)
pr="<w:pPr>#{style ? "<w:pStyle w:val=\"#{style}\"/>" : ''}<w:spacing w:after=\"#{after}\" w:line=\"280\" w:lineRule=\"auto\"/>#{style ? '<w:keepNext/>' : ''}</w:pPr>"
rpr="<w:rPr>#{bold ? '<w:b/>' : ''}#{color ? "<w:color w:val=\"#{color}\"/>" : ''}#{size ? "<w:sz w:val=\"#{size}\"/>" : ''}</w:rPr>"
"<w:p>#{pr}<w:r>#{rpr}<w:t xml:space=\"preserve\">#{esc(s)}</w:t></w:r></w:p>"
end
def bullet(s);para("•  #{s}",size:20,after:80);end
def table(rows,widths)
"<w:tbl><w:tblPr><w:tblW w:w=\"9638\" w:type=\"dxa\"/><w:tblLayout w:type=\"fixed\"/><w:tblCellMar><w:top w:w=\"100\" w:type=\"dxa\"/><w:left w:w=\"110\" w:type=\"dxa\"/><w:bottom w:w=\"100\" w:type=\"dxa\"/><w:right w:w=\"110\" w:type=\"dxa\"/></w:tblCellMar></w:tblPr><w:tblGrid>"+widths.map{|w|"<w:gridCol w:w=\"#{w}\"/>"}.join+"</w:tblGrid>"+rows.each_with_index.map{|row,i|"<w:tr><w:trPr><w:cantSplit/>#{i==0 ? '<w:tblHeader/>' : ''}</w:trPr>"+row.each_with_index.map{|v,j|"<w:tc><w:tcPr><w:tcW w:w=\"#{widths[j]}\" w:type=\"dxa\"/><w:shd w:fill=\"#{i==0 ? '6B1738' : (i.odd? ? 'F8EEF2' : 'FFFFFF')}\"/></w:tcPr>"+para(v,size:18,color:i==0 ? 'FFFFFF' : '21171C',bold:i==0,after:20)+"</w:tc>"}.join+"</w:tr>"}.join+"</w:tbl>"
end
def newpage;'<w:p><w:pPr><w:spacing w:after="0"/></w:pPr><w:r><w:br w:type="page"/></w:r></w:p>';end
rows=[['Data','Formato','Proposta','O que precisamos captar'],['17/10 · sáb','Reel','Depoimentos + conversa da Margô','Material já em edição; finalizar os motions.']]+POSTS.map{|p|["#{p[:date]} · #{p[:day][0,3].downcase}",p[:format].split(' · ').first.capitalize,p[:title],case p[:date];when '20/10';'Mesinha, vista, pedido montado e cadeira limpa para a personagem.';when '22/10';'Focaccia, molhos, café e som real.';when '24/10';'Chegada, luz da manhã, mesa e permanência.';when '27/10';'Equipe orientando, preparo e serviço do café.';when '29/10';'Cozinha, preparo, finalização e entrega do pedido.';else;'Pessoas, encontros, pausa individual e ambiente.';end]}
xml=para('MARGÔ CAFÉS ESPECIAIS',color:'ED5F67',size:20,bold:true)+para('Calendário de conteúdo',style:'Title')+para('17 a 31 de outubro de 2026 · propostas e captação',color:'6E5D65',size:24)+para('Direção desta etapa',style:'Heading2')+para('Trazer mais visitas mostrando a atmosfera, as pessoas e o sentimento de estar na Margô. Café e comida fazem parte da experiência. Com uma semana de operação, as pautas são testes: não partem de metas de venda por produto ou de dias considerados fracos.')+para('3 posts por semana · captação presencial em 18/10 · versão para aprovação de ideias',color:'6E5D65',size:20)+para('Calendário',style:'Heading2')+table(rows,[1300,1500,3050,3788])+para('O vídeo de 17/10 já está em produção. As seis novas pautas serão ajustadas ao material realmente captado. Este documento não inclui copies, legendas ou falas finais.',size:20,color:'6E5D65')
html_pages=[]
intro='<div class="eyebrow">MARGÔ CAFÉS ESPECIAIS</div><h1>Calendário de conteúdo</h1><div class="subtitle">17 a 31 de outubro de 2026 · propostas e captação</div><h2>Direção desta etapa</h2><p>Trazer mais visitas mostrando a atmosfera, as pessoas e o sentimento de estar na Margô. Café e comida fazem parte da experiência. Com uma semana de operação, as pautas são testes: não partem de metas de venda por produto ou de dias considerados fracos.</p><p class="muted">3 posts por semana · captação presencial em 18/10 · versão para aprovação de ideias</p><h2>Calendário</h2><table>'+rows.each_with_index.map{|row,i|'<tr>'+row.map{|v|"<#{i==0 ? 'th' : 'td'}>#{esc(v)}</#{i==0 ? 'th' : 'td'}>"}.join+'</tr>'}.join+'</table><p class="muted small">O vídeo de 17/10 já está em produção. As seis novas pautas serão ajustadas ao material realmente captado. Sem copies, legendas ou falas finais nesta etapa.</p>'
