xml+=newpage+para("#{p[:date]}   #{p[:day]}   |   #{p[:format]}",color:'ED5F67',size:18,bold:true)+para(p[:title],style:'Heading1')+para(p[:purpose],color:'6E5D65',size:21)+para('Ideia central',style:'Heading3')+para(p[:idea])+para('O que precisa aparecer',style:'Heading3')+p[:show].map{|s|bullet(s)}.join+para('Materiais para captar · domingo 18/10',style:'Heading3')+para('Fotos',bold:true,size:20)+p[:photos].map{|s|bullet(s)}.join+para('Vídeos e som',bold:true,size:20)+p[:videos].map{|s|bullet(s)}.join+para('Pessoas e participação',style:'Heading3')+para(p[:people],size:20)+para('Cuidados e alternativas',style:'Heading3')+para(p[:note],size:20)+para('Para aprovar',style:'Heading3')+para(p[:approval],size:20)
list=->(a){'<ul>'+a.map{|s|'<li>'+esc(s)+'</li>'}.join+'</ul>'}
