end
blocks=[['Prioridade 1 · mesinha e manhã','Mesa vazia e montada, cadeira para a personagem, vista de quem senta, chegada à casa e pedido servido. Alimenta 20 e 24/10.'],['Prioridade 2 · café e comida em ação','Focaccia, molhos, café servido; preparo e entrega do Croque ou de outro prato viável. Alimenta 22 e 29/10.'],['Prioridade 3 · pessoas e acolhimento','Orientação de café pela equipe, mãos e gestos; duas pessoas conversando e uma pausa individual. Alimenta 27 e 31/10.'],['Banco transversal','Fachada e caminho real, planos abertos, mural, louças, plantas, detalhes de luz, pedidos à mesa e som ambiente. Fotografar e gravar antes de consumir os produtos.'],['Cuidados de captação','Vídeos verticais, clipes estáveis de 5 a 8 segundos e sobra antes/depois da ação. Para cada situação, fazer plano aberto, médio e detalhe. Combinar a participação das pessoas e priorizar momentos reais, sem atrapalhar o atendimento.'],['Como usar este planejamento','Aprovar primeiro as ideias. Depois da visita de domingo, conferir o banco captado, confirmar formato e só então escrever copies e legendas. Trocar a ordem das pautas se a captação pedir, mantendo três posts por semana. Stories continuam orgânicos.']]
refs=[['Referência enviada · Reel','https://www.instagram.com/reel/DeSKlRFoBRR/'],['Referência enviada · publicação','https://www.instagram.com/p/DdYLOgRjGG1/']]
xml+=newpage+para('18/10   DOMINGO   |   GUIA DE CAPTAÇÃO',color:'ED5F67',size:18,bold:true)+para('Uma visita, várias pautas',style:'Heading1')
blocks.each{|h,t|xml+=para(h,style:'Heading3')+para(t,size:20)}
xml+=para('Referências das sócias',style:'Heading3')+para('A sugestão da mesinha enviada pela Bruna foi incorporada em 20/10. Os dois links abaixo ficaram sem acesso ao conteúdo nesta consulta. Permanecem como referências a conferir; não foram interpretados como tendências ou ideias já analisadas.',size:20)
