footer=File.join(stage,'word/footer1.xml');File.write(footer,File.read(footer).gsub('Conteúdos de pré-lançamento','Calendário de conteúdo · outubro'))
core=File.join(stage,'docProps/core.xml');text=File.read(core).sub(/<dc:title>.*?<\/dc:title>/m,'<dc:title>Margô — calendário de conteúdo e captação — 17 a 31 de outubro de 2026</dc:title>');File.write(core,text)
