html='<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Margô · Calendário de conteúdo</title><style>@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;background:#e9e5e5;color:#21171c;font-family:Arial,sans-serif;font-size:10.5pt;line-height:1.35}.page{position:relative;width:210mm;min-height:297mm;height:297mm;margin:14px auto;background:white;padding:20mm;page-break-after:always;overflow:hidden}.page:last-child{page-break-after:auto}h1{font:26pt Georgia,serif;margin:4px 0 8px}h1.post-title{font-size:22pt}h2{font:15pt Georgia,serif;color:#6b1738;margin:17px 0 10px}h3{font-size:9pt;text-transform:uppercase;letter-spacing:1px;color:#6e5d65;margin:14px 0 6px}h4{font-size:10pt;margin:8px 0 4px}p{margin:0 0 8px}ul{margin:0 0 8px;padding-left:17px}li{margin-bottom:4px}.eyebrow{color:#ed5f67;font-weight:bold;letter-spacing:2px;font-size:10pt}.subtitle{font-size:12pt;color:#6e5d65;margin-bottom:15px}.date{font-size:9pt;color:#ed5f67;font-weight:bold;letter-spacing:.5px;margin-bottom:8px}.purpose{font-style:italic;color:#6e5d65;border-bottom:1px solid #f6dde9;padding-bottom:12px;margin-bottom:14px}.muted{color:#6e5d65}.small{font-size:9pt}table{border-collapse:collapse;width:100%;font-size:9pt;margin-bottom:12px}th{background:#6b1738;color:white;text-align:left}td,th{padding:8px;vertical-align:top}tr:nth-child(even){background:#f8eef2}th:first-child{width:14%}th:nth-child(2){width:16%}th:nth-child(3){width:32%}.approval{padding:2px 10px 5px;background:#f8eef2;margin-top:9px}.approval h3{margin-top:8px}.footer{position:absolute;bottom:11mm;right:20mm;font-size:8pt;color:#6e5d65}a{color:#6b1738}@media print{body{background:white}.page{margin:0}}</style>'+html_pages.each_with_index.map{|page,i|"<section class=\"page\">#{page}<div class=\"footer\">Margô · Calendário de conteúdo · outubro &nbsp; <b>#{i+1}</b></div></section>"}.join+'<script>if(location.hash){const i=Number(location.hash.slice(1));document.querySelectorAll(".page").forEach((p,n)=>{if(n!==i-1)p.remove()});}</script></html>'
